// ═══════════════════════════════════════════════════════════════════════════════
// LATEST TRENDING NEWS FILTER v2.0
// Filters last 24 hours, removes duplicates, sorts by recency
// ═══════════════════════════════════════════════════════════════════════════════

const allItems = $input.all();
const now = new Date();
const last24Hours = new Date(now.getTime() - 24 * 60 * 60 * 1000);

// Track seen headlines to remove duplicates
const seenHeadlines = new Set();

const processedItems = allItems
  .filter(i => i.json.url || i.json.link)
  .map(i => {
    // Parse publication date from various possible fields
    let pubDate = null;
    const dateFields = ['pubDate', 'isoDate', 'date', 'published', 'updated'];

    for (const field of dateFields) {
      if (i.json[field]) {
        pubDate = new Date(i.json[field]);
        if (!isNaN(pubDate.getTime())) break;
      }
    }

    return {
      ...i,
      parsedDate: pubDate,
      headline: i.json.title || i.json.headline || ''
    };
  })
  // Remove duplicates by headline
  .filter(i => {
    const normalizedHeadline = i.headline.toLowerCase().trim();
    if (seenHeadlines.has(normalizedHeadline)) {
      return false;
    }
    seenHeadlines.add(normalizedHeadline);
    return true;
  })
  // Filter: Only last 24 hours
  .filter(i => {
    if (!i.parsedDate || isNaN(i.parsedDate.getTime())) {
      return true; // Keep if no valid date
    }
    return i.parsedDate >= last24Hours;
  })
  // Sort: Newest first
  .sort((a, b) => {
    const dateA = a.parsedDate ? a.parsedDate.getTime() : 0;
    const dateB = b.parsedDate ? b.parsedDate.getTime() : 0;
    return dateB - dateA;
  })
  // Take top 10
  .slice(0, 10)
  // Clean up
  .map(i => {
    delete i.parsedDate;
    delete i.headline;
    return i;
  });

// If less than 10 items after filtering, log warning
if (processedItems.length < 10) {
  console.log(`Warning: Only ${processedItems.length} recent news items found`);
}

return processedItems;

return [
  {
    json: {
      items: $input.all().map(i => {
        // Get URL - RSS feeds use 'link', not 'url'
        const url = i.json.url || i.json.link || i.json.href || null;

        // Get headline
        const headline = i.json.title || i.json.headline || 'Untitled';

        // Extract source from title if not available
        let source = i.json.source || '';
        if (!source && headline.includes(' - ')) {
          const parts = headline.split(' - ');
          source = parts[parts.length - 1].trim();
        }

        // Get summary from available fields
        const summary = i.json.summary || i.json.description || i.json.contentSnippet || '';

        return {
          headline: headline,
          url: url,
          source: source,
          summary: summary
        };
      })
    }
  }
];

